/**
 * The compile engine (spec §6, §7): manifest source → IR → plugins → final file contents.
 *
 * Pure: no file system, clock or environment. The CLI writes what this returns. Every
 * file gets the `@generated` header with one fingerprint over the canonical IR, the
 * plugin configs, the urn-forge version and the plugin names and versions, so a change
 * to any of them shows up as drift.
 */
import * as v from 'valibot';
import { hasErrors, type Diagnostic } from './diagnostics.js';
import { buildIrFromSource } from './ir/build.js';
import { compareCodeUnits, fingerprint } from './ir/canonical.js';
import type { UniversalIR } from './ir/types.js';
import { fcisPlugin } from './plugins/fcis.plugin.js';
import type { CodegenPlugin, GeneratedArtifact } from './plugins/plugin.interface.js';
import { valibotPlugin } from './plugins/valibot.plugin.js';
import { GENERATOR_VERSION } from './version.js';

export type { Diagnostic } from './diagnostics.js';

/** A plugin together with its config, in run order. */
export interface PluginEntry {
  readonly plugin: CodegenPlugin<any>;
  readonly config: unknown;
}

/** The MVP's fixed plugin list. A config file (spec §7.5) replaces this later. */
export const DEFAULT_PLUGINS: readonly PluginEntry[] = [
  { plugin: valibotPlugin, config: {} },
  { plugin: fcisPlugin, config: {} },
];

export interface CompileResult {
  /** Empty whenever `diagnostics` holds an error. Sorted by path. */
  readonly files: readonly GeneratedArtifact[];
  readonly diagnostics: readonly Diagnostic[];
  readonly ir?: UniversalIR;
  readonly fingerprint?: string;
}

export function generatedHeader(fingerprintValue: string): string {
  return `// @generated by urn-forge ${GENERATOR_VERSION} — do not edit\n// fingerprint: ${fingerprintValue}\n`;
}

/** LF line endings and exactly one trailing newline. */
function normalize(content: string): string {
  return `${content.replace(/\r\n?/g, '\n').replace(/\n*$/, '')}\n`;
}

export function compile(manifestSource: string, plugins: readonly PluginEntry[] = DEFAULT_PLUGINS): CompileResult {
  const built = buildIrFromSource(manifestSource);
  if (!built.success) {
    return {
      files: [],
      diagnostics: built.issues.map(({ code, urn, message, location }) => ({
        code,
        severity: 'error' as const,
        message,
        ...(urn === undefined ? {} : { urn }),
        ...(location === undefined ? {} : { location }),
      })),
    };
  }
  const { ir, locator } = built;

  const diagnostics: Diagnostic[] = [];
  const configs: unknown[] = [];
  for (const { plugin, config } of plugins) {
    const parsed = v.safeParse(plugin.configSchema, config);
    if (!parsed.success) {
      for (const issue of parsed.issues) {
        diagnostics.push({ code: 'plugin-config', severity: 'error', message: `plugin ${plugin.name} config: ${issue.message}` });
      }
    }
    configs.push(parsed.success ? parsed.output : config);
  }
  if (diagnostics.length > 0) return { files: [], diagnostics, ir };

  const print = fingerprint({
    ir,
    config: plugins.map(({ plugin }, i) => [plugin.name, configs[i]]),
    generatorVersion: GENERATOR_VERSION,
    plugins: plugins.map(({ plugin }) => ({ name: plugin.name, version: plugin.version })),
  });
  const header = generatedHeader(print);

  const files = new Map<string, GeneratedArtifact>();
  plugins.forEach(({ plugin }, i) => {
    const output = plugin.emit(ir, configs[i]);
    for (const diagnostic of output.diagnostics) {
      const location = diagnostic.urn === undefined ? undefined : locator?.locateUrn(diagnostic.urn);
      diagnostics.push(location ? { ...diagnostic, location } : diagnostic);
    }
    for (const artifact of output.artifacts) {
      if (files.has(artifact.relativePath)) {
        diagnostics.push({
          code: 'output-conflict',
          severity: 'error',
          message: `plugin ${plugin.name} writes ${artifact.relativePath}, which another plugin already wrote`,
        });
        continue;
      }
      files.set(artifact.relativePath, {
        relativePath: artifact.relativePath,
        content: normalize(`${header}\n${artifact.content}`),
      });
    }
  });

  if (hasErrors(diagnostics)) return { files: [], diagnostics, ir, fingerprint: print };
  const sorted = [...files.values()].sort((a, b) => compareCodeUnits(a.relativePath, b.relativePath));
  return { files: sorted, diagnostics, ir, fingerprint: print };
}
